package saver

import (
	"context"
	"testing"
)

type gsrWitnessFakeStore struct {
	calls int
}

func (s *gsrWitnessFakeStore) Put(ctx context.Context, key, value string) error {
	s.calls++
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	store := &gsrWitnessFakeStore{}
	_ = Save(ctx, store, "id", "a", "b")

	if store.calls >= 2 {
		t.Fatalf("store.calls = %v, want < 2", store.calls)
	}
}

