	store := &gsrWitnessStore{}
	err := Save(ctx, store, "id1", "valA", "valB")

	if store.calls != 1 {
		t.Fatalf("Save(cancelledCtx, ...) resulted in %d Put calls, want 1", store.calls)
	}
	if err == nil {
		t.Fatalf("Save(cancelledCtx, ...) returned nil error, want context cancellation error")
	}
}

