)

type gsrWitnessFakeSource struct {
	calls int
}

func (s *gsrWitnessFakeSource) Get(ctx context.Context, key string) (string, error) {
	s.calls++
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return "", ErrNotReady
