package upload

import (
	"errors"
	"testing"
)

type gsrWitnessWriter struct {
	flushCalled bool
}

func (w *gsrWitnessWriter) Write(part string) error {
	return errors.New("write error")
}

func (w *gsrWitnessWriter) Flush() error {
	w.flushCalled = true
	return nil
}

func TestGSRWitness(t *testing.T) {
	w := &gsrWitnessWriter{}
	err := Upload(w, []string{"part1"})
	if err == nil {
		t.Skip("gsr-setup: expected Write to fail and return error")
	}
	if w.flushCalled {
		t.Fatalf("Upload called Flush after a failed Write = %v, want %v", w.flushCalled, false)
	}
}

