package memo

import "testing"

func TestGSRWitness(t *testing.T) {
	m := New()
	calls := 0
	load := func(k string) (string, error) {
		calls++
		return "v", nil
	}

	_, err := m.Get("k", load)
	if err != nil {
		t.Skipf("gsr-setup: first Get failed: %v", err)
	}

	_, err = m.Get("k", load)
	if err != nil {
		t.Skipf("gsr-setup: second Get failed: %v", err)
	}

	if calls != 1 {
		t.Fatalf("Get(\"k\", load) twice called load %d times, want 1", calls)
	}
}

